const express = require('express');
const crypto = require('crypto');
const argon2 = require('argon2');
const fs = require('fs');
const path = require('path');

const app = express();
app.use(express.json());

const TOKENS_DIR = path.resolve('/var/app/tokens');
const API_KEYS = new Map();
const RATE_LIMIT = new Map();

// Constant-time comparison to prevent timing attacks
function safeCompare(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');
  if (bufA.length !== bufB.length) {
    // Pad shorter to match longer, preventing length oracle
    const maxLen = Math.max(bufA.length, bufB.length);
    const paddedA = Buffer.alloc(maxLen, 0);
    const paddedB = Buffer.alloc(maxLen, 0);
    bufA.copy(paddedA);
    bufB.copy(paddedB);
    // Always do full comparison even when lengths differ
    return crypto.timingSafeEqual(paddedA, paddedB) && bufA.length === bufB.length;
  }
  return crypto.timingSafeEqual(bufA, bufB);
}

// Rate limiting middleware
function rateLimit(req, res, next) {
  const ip = req.ip;
  const now = Date.now();
  const window = RATE_LIMIT.get(ip) || { count: 0, start: now };
  if (now - window.start > 60000) {
    RATE_LIMIT.set(ip, { count: 1, start: now });
  } else {
    window.count++;
    if (window.count > 100) {
      return res.status(429).json({ error: 'Rate limited' });
    }
    RATE_LIMIT.set(ip, window);
  }
  next();
}

app.use(rateLimit);

// Generate API key for a service
app.post('/api/keys/generate', async (req, res) => {
  const { serviceName, adminSecret } = req.body;
  if (!serviceName || !adminSecret) {
    return res.status(400).json({ error: 'Missing fields' });
  }

  const expectedSecret = process.env.ADMIN_SECRET;
  if (!expectedSecret || !safeCompare(adminSecret, expectedSecret)) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const apiKey = crypto.randomBytes(32).toString('hex');
  const keyHash = await argon2.hash(apiKey);
  API_KEYS.set(serviceName, { hash: keyHash, created: Date.now() });

  return res.json({ apiKey, serviceName });
});

// Validate API key - used by internal services
app.post('/api/keys/validate', (req, res) => {
  const { serviceName, apiKey } = req.body;
  if (!serviceName || !apiKey) {
    return res.status(400).json({ error: 'Missing fields' });
  }

  const entry = API_KEYS.get(serviceName);
  if (!entry) {
    return res.status(404).json({ error: 'Service not found' });
  }

  // Verify using argon2 (safe against timing)
  argon2.verify(entry.hash, apiKey)
    .then(valid => {
      if (valid) {
        res.json({ valid: true, serviceName });
      } else {
        res.status(401).json({ valid: false });
      }
    })
    .catch(() => res.status(500).json({ error: 'Verification failed' }));
});

// Token-based file access system
const accessTokens = new Map();

app.post('/api/tokens/create', (req, res) => {
  const { adminSecret, filePath, expiresIn } = req.body;
  if (!adminSecret || !filePath) {
    return res.status(400).json({ error: 'Missing fields' });
  }

  const expectedSecret = process.env.ADMIN_SECRET;
  if (!expectedSecret || !safeCompare(adminSecret, expectedSecret)) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  // Sanitize file path
  const safeName = path.basename(filePath);
  const fullPath = path.join(TOKENS_DIR, safeName);
  const resolved = path.resolve(fullPath);
  if (!resolved.startsWith(TOKENS_DIR + path.sep)) {
    return res.status(400).json({ error: 'Invalid path' });
  }

  const token = crypto.randomBytes(24).toString('hex');
  const expiry = Date.now() + (expiresIn || 3600000);
  accessTokens.set(token, { path: resolved, expiry });

  return res.json({ token, expires: new Date(expiry).toISOString() });
});

// Access file with token
app.get('/api/files/:token', (req, res) => {
  const { token } = req.params;

  if (!token || token.length > 200) {
    return res.status(400).json({ error: 'Invalid token format' });
  }

  // Find matching token using constant-time comparison
  let matchedEntry = null;
  for (const [storedToken, entry] of accessTokens.entries()) {
    if (safeCompare(token, storedToken)) {
      matchedEntry = entry;
      break;
    }
  }

  if (!matchedEntry) {
    return res.status(404).json({ error: 'Token not found' });
  }

  if (Date.now() > matchedEntry.expiry) {
    accessTokens.delete(token);
    return res.status(410).json({ error: 'Token expired' });
  }

  // Verify path is still safe
  if (!matchedEntry.path.startsWith(TOKENS_DIR + path.sep)) {
    return res.status(403).json({ error: 'Access denied' });
  }

  res.sendFile(matchedEntry.path);
});

// Webhook signature verification
app.post('/api/webhooks/receive', (req, res) => {
  const signature = req.headers['x-webhook-signature'];
  const webhookSecret = process.env.WEBHOOK_SECRET;

  if (!signature || !webhookSecret) {
    return res.status(401).json({ error: 'Missing signature' });
  }

  const payload = JSON.stringify(req.body);
  const expected = crypto.createHmac('sha256', webhookSecret)
    .update(payload)
    .digest('hex');

  if (!safeCompare(signature, expected)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // Process webhook
  const { event, data } = req.body;
  if (event && data) {
    console.log(`Webhook received: ${event}`);
  }

  res.json({ received: true });
});

app.listen(3000);
module.exports = app;
